CREATE COLUMN TABLE "TEST_AP"."OISR" ("RequestNum" INTEGER CS_INT NOT NULL , "Open_Date" LONGDATE CS_LONGDATE, "Open_Time" INTEGER CS_INT, "Task_Id" INTEGER CS_INT, "Contact" NVARCHAR(30), "Phone" NVARCHAR(20), "TaskType" SMALLINT CS_INT DEFAULT 0, "Dscription" NVARCHAR(254), "Answer" NCLOB MEMORY THRESHOLD 1000, "Status" NVARCHAR(1) DEFAULT 'O', PRIMARY KEY ("RequestNum")) UNLOAD PRIORITY 5  AUTO MERGE 